begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_temp;
select no_plan();
insert into auth.users(id) values(md5('selection_a')::uuid),(md5('selection_b')::uuid);
insert into profiles(id,display_name) values(md5('selection_a')::uuid,'A'),(md5('selection_b')::uuid,'B');
insert into account_preferences(owner_id,scheduling_timezone) values(md5('selection_a')::uuid,'UTC'),(md5('selection_b')::uuid,'UTC');
create function pg_temp.rotation(n integer) returns uuid language plpgsql security invoker as $$
declare root uuid;day uuid;
begin
 insert into public.programs(owner_id,name,cycle_length,objective,duration_rotations) values(auth.uid(),'Progression rotation '||n,n,'hypertrophy',1) returning id into root;
 for i in 1..n loop
 insert into public.program_days(owner_id,program_id,cycle_length,cycle_position,name,is_rest_day) values(auth.uid(),root,n,i,'Workout '||i,i%2=0) returning id into day;
 if i%2<>0 then insert into public.program_slots(owner_id,program_day_id,position,movement_pattern_id,exercise_id,target_sets,target_reps_min,target_reps_max,required_exercise_type,primary_muscle_id) values(auth.uid(),day,1,(select id from public.movement_patterns where slug='horizontal_push'),(select id from public.exercises where slug='barbell_bench_press'),2,8,12,'compound',(select id from public.muscle_groups where slug='pectorals'));end if;
 end loop;return public.snapshot_program(root);
end $$;
create function pg_temp.finish_day(v uuid,d int,nonce text) returns uuid language plpgsql security invoker as $$
declare w uuid;m uuid;e uuid;s public.workout_sets;
begin
 w:=public.start_program_workout(v,d,md5(nonce)::uuid);
 select id into m from public.workout_movements where workout_session_id=w and owner_id=auth.uid() limit 1;
 e:=public.select_program_exercise(m,(select id from public.exercises where slug='barbell_bench_press'),null,gen_random_uuid());
 for s in select * from public.workout_sets where workout_exercise_id=e and owner_id=auth.uid() order by position loop
 perform public.log_workout_set(p_item=>e,p_id=>s.id,p_operation=>'save',p_revision=>s.revision,p_mutation=>gen_random_uuid(),p_reps=>12,p_weight=>50,p_type=>'working',p_completed=>true);
 end loop;
 perform public.end_workout(w,'completed');return w;
end $$;

create function pg_temp.decide(k text,nonce text,target date default null,s uuid default null) returns uuid language plpgsql as $$
declare a uuid;c jsonb;v uuid;
begin
 select id,source_version_id into a,v from program_assignments where owner_id=auth.uid() and state='active';c:=program_schedule_cursor(a);
 return decide_program_schedule(a,v,(c->>'dayId')::uuid,(c->>'rotation')::int,(c->>'workIndex')::bigint,(c->>'decisionRevision')::bigint,k,md5(nonce)::uuid,s,target);
end $$;
set local role authenticated;
select set_config('request.jwt.claims',json_build_object('sub',md5('selection_a')::uuid,'role','authenticated')::text,true);
select set_config('body_test.v',pg_temp.rotation(7)::text,true);
select set_config('body_test.w',start_program_workout(current_setting('body_test.v')::uuid,1,md5('selection_initial')::uuid)::text,true);
select set_config('body_test.a',(select program_assignment_id::text from workout_sessions where id=current_setting('body_test.w')::uuid),true);
select set_config('body_test.c',program_schedule_cursor(current_setting('body_test.a')::uuid)::text,true);
select throws_ok($$select pg_temp.decide('skip','active_skip')$$,'23514',null,'active workout protects scheduling intent');
select end_workout(current_setting('body_test.w')::uuid,'completed');
select set_config('body_test.p',start_program_workout(current_setting('body_test.v')::uuid,1,md5('selection_partial')::uuid)::text,true);
select set_config('body_test.m',(select id::text from workout_movements where workout_session_id=current_setting('body_test.p')::uuid),true);
select set_config('body_test.e',select_program_exercise(current_setting('body_test.m')::uuid,(select id from exercises where slug='barbell_bench_press'),null,md5('selection_partial_pick')::uuid)::text,true);
select log_workout_set(p_item=>current_setting('body_test.e')::uuid,p_id=>(select id from workout_sets where workout_exercise_id=current_setting('body_test.e')::uuid order by position limit 1),p_operation=>'save',p_revision=>0,p_mutation=>md5('selection_partial_set')::uuid,p_reps=>12,p_weight=>50,p_type=>'working',p_completed=>true);
select end_workout(current_setting('body_test.p')::uuid,'completed');
select is((program_schedule_cursor(current_setting('body_test.a')::uuid)->>'position')::int,1,'partial remains recommended until accepted');
select set_config('body_test.accept',pg_temp.decide('accept_partial','accept',null,current_setting('body_test.p')::uuid)::text,true);
select is((program_schedule_cursor(current_setting('body_test.a')::uuid)->>'position')::int,3,'acceptance resolves only its exact occurrence');
select is((select completion_status from workout_sessions where id=current_setting('body_test.p')::uuid),'partial','accepted actual session stays partial');
select is((select count(*)::int from workout_sets where workout_exercise_id=current_setting('body_test.e')::uuid and status='completed'),1,'acceptance invents no missing sets');
select is((program_schedule_cursor(current_setting('body_test.a')::uuid)->>'completedRotations')::int,0,'accepted partial is not a full rotation');
select is(decide_program_schedule(current_setting('body_test.a')::uuid,current_setting('body_test.v')::uuid,(current_setting('body_test.c')::jsonb->>'dayId')::uuid,0,0,0,'accept_partial',md5('accept')::uuid,current_setting('body_test.p')::uuid),current_setting('body_test.accept')::uuid,'retry after advancement is payload-bound idempotent');
select throws_ok($$select decide_program_schedule(current_setting('body_test.a')::uuid,current_setting('body_test.v')::uuid,(current_setting('body_test.c')::jsonb->>'dayId')::uuid,0,0,0,'skip',md5('accept')::uuid)$$,'23514',null,'a request cannot be repurposed');
select set_config('body_test.skip',pg_temp.decide('skip','skip_next')::text,true);
select is((program_schedule_cursor(current_setting('body_test.a')::uuid)->>'position')::int,5,'skip resolves the next outstanding occurrence');
select is((select count(*)::int from workout_sessions where program_assignment_id=current_setting('body_test.a')::uuid),2,'skip never creates a session');
select is((select actor_id from program_schedule_decisions where id=current_setting('body_test.skip')::uuid),auth.uid(),'skip actor is verified owner');
select is((select session_id from program_schedule_decisions where id=current_setting('body_test.skip')::uuid),null::uuid,'skip contains no fake performance reference');
select set_config('body_test.c2',program_schedule_cursor(current_setting('body_test.a')::uuid)::text,true);
select set_config('body_test.defer',pg_temp.decide('defer','defer',current_date+4)::text,true);
select is((program_schedule_cursor(current_setting('body_test.a')::uuid)->>'position')::int,5,'deferral does not advance');
select is((program_schedule_cursor(current_setting('body_test.a')::uuid)->>'readyOn')::date,current_date+4,'defer target controls future readiness');
select is(program_schedule_cursor(current_setting('body_test.a')::uuid)->>'dueOn',current_setting('body_test.c2')::jsonb->>'dueOn','original due date retained');
select throws_ok($$select decide_program_schedule(current_setting('body_test.a')::uuid,current_setting('body_test.v')::uuid,(current_setting('body_test.c2')::jsonb->>'dayId')::uuid,0,(current_setting('body_test.c2')::jsonb->>'workIndex')::bigint,2,'defer',md5('stale_defer')::uuid,null,current_date+5)$$,'40001',null,'same cursor with stale decision revision cannot extend defer');
select throws_ok($$select pg_temp.decide('defer','duplicate_target',current_date+4)$$,'23514',null,'a new request cannot duplicate the same deferral date');
select lives_ok($$select pg_temp.decide('defer','replace_defer',current_date+3)$$,'deferral can be replaced with a valid earlier future date');
select is((program_schedule_cursor(current_setting('body_test.a')::uuid)->>'readyOn')::date,current_date+3,'replacement respects natural recovery rather than old defer date');
select lives_ok($$select pg_temp.decide('cancel_defer','cancel_defer')$$,'explicit cancellation supported');
select is(program_schedule_cursor(current_setting('body_test.a')::uuid)->>'deferredUntil',null::text,'cancel returns to natural schedule');
select is((select count(*)::int from program_schedule_decisions where assignment_id=current_setting('body_test.a')::uuid and kind in('defer','cancel_defer')),3,'all defer intentions retained immutably');
select throws_ok($$select pg_temp.decide('defer','past_defer',current_date)$$,'22023',null,'nonfuture local date rejected');
select throws_ok($$select pg_temp.decide('defer','huge_defer',current_date+367)$$,'22023',null,'deferral bounded to one year');
select ok(exists(select 1 from jsonb_array_elements(program_schedule()->'events')e where e->>'status'='skipped'),'calendar distinguishes skips');
select ok(exists(select 1 from jsonb_array_elements(program_schedule()->'events')e where e->>'status'='accepted_partial'),'calendar distinguishes partial acceptance');
select ok(exists(select 1 from jsonb_array_elements(program_schedule()->'events')e where e->>'status'='deferred'),'calendar preserves defer event');
select throws_ok($$update program_schedule_decisions set kind='skip' where id=current_setting('body_test.accept')::uuid$$,'42501',null,'decision updates denied');
select throws_ok($$delete from program_schedule_decisions where id=current_setting('body_test.accept')::uuid$$,'42501',null,'decision deletion denied');
select set_config('body_test.ooo',pg_temp.finish_day(current_setting('body_test.v')::uuid,7,'choice_7')::text,true);
select is((select source_cycle_position::int from workout_sessions where id=current_setting('body_test.ooo')::uuid),7,'alternative keeps actual source day');
select is((program_schedule_cursor(current_setting('body_test.a')::uuid)->>'position')::int,5,'alternative does not resolve another position');
select set_config('body_test.repeat',pg_temp.finish_day(current_setting('body_test.v')::uuid,7,'choice_repeat7')::text,true);
select is((select source_rotation from workout_sessions where id=current_setting('body_test.repeat')::uuid),0,'repeat stays within explicit current rotation');
select is((select count(distinct work_index)::int from program_schedule_resolutions(current_setting('body_test.a')::uuid)),3,'repeat never consumes another position');
select set_config('body_test.full5',pg_temp.finish_day(current_setting('body_test.v')::uuid,5,'choice_5')::text,true);
select is((program_schedule_cursor(current_setting('body_test.a')::uuid)->>'rotation')::int,1,'resolved positions advance cursor rotation');
select is((program_schedule_cursor(current_setting('body_test.a')::uuid)->>'completedRotations')::int,0,'skip/accepted partial cannot fabricate full rotation');
select is((program_schedule_cursor(current_setting('body_test.a')::uuid)->>'complete')::boolean,false,'fixed-duration full-rotation requirement remains unmet');
select ok(exists(select 1 from jsonb_array_elements(program_progression_evidence(current_setting('body_test.full5')::uuid)->0->'history')e where e->>'sessionId'=current_setting('body_test.full5')),'closed progression evidence includes the just-completed session');
select set_config('body_test.day',(select d->>'id' from program_versions v cross join lateral jsonb_array_elements(v.definition->'days')d where v.id=current_setting('body_test.v')::uuid and (d->>'cycle_position')::int=1),true);
select set_config('body_test.favorite',save_favorite_workout('program_day',current_setting('body_test.v')::uuid,current_setting('body_test.day')::uuid,'Saved press',md5('favorite_program')::uuid)::text,true);
select is(save_favorite_workout('program_day',current_setting('body_test.v')::uuid,current_setting('body_test.day')::uuid,'Saved press',md5('favorite_program')::uuid),current_setting('body_test.favorite')::uuid,'favorite save retry idempotent');
select is(save_favorite_workout('program_day',current_setting('body_test.v')::uuid,current_setting('body_test.day')::uuid,'Another name',md5('favorite_same_source')::uuid),current_setting('body_test.favorite')::uuid,'same source deduplicates instead of silently creating copies');
select is((select (definition->0->>'target_sets')::int from favorite_workouts where id=current_setting('body_test.favorite')::uuid),2,'program prescription preserved');
select is((select source_type from favorite_workouts where id=current_setting('body_test.favorite')::uuid),'program_day','source type retained');
select set_config('body_test.before',program_schedule_cursor(current_setting('body_test.a')::uuid)::text,true);
select set_config('body_test.fw',start_favorite_workout(current_setting('body_test.favorite')::uuid,md5('favorite_start')::uuid)::text,true);
select is(start_favorite_workout(current_setting('body_test.favorite')::uuid,md5('favorite_start')::uuid),current_setting('body_test.fw')::uuid,'favorite start retries do not create sessions');
select ok((select program_assignment_id is null and source_program_version_id is null and source_program_day_id is null and source_rotation is null and source_cycle_position is null from workout_sessions where id=current_setting('body_test.fw')::uuid),'favorite launch has no accidental assignment/rotation identity');
select is((select count(*)::int from workout_movements where workout_session_id=current_setting('body_test.fw')::uuid),1,'saved structure enters normal movement-first Home');
select is((select count(*)::int from workout_exercises where workout_session_id=current_setting('body_test.fw')::uuid),0,'favorite begins unselected, without fabricated actuals');
select is(program_schedule_cursor(current_setting('body_test.a')::uuid)::text,current_setting('body_test.before'),'favorite start never changes program cursor');
select throws_ok($$select start_favorite_workout(current_setting('body_test.favorite')::uuid,md5('favorite_second_active')::uuid)$$,'23514',null,'favorite respects single active session');
select set_config('body_test.fm',(select id::text from workout_movements where workout_session_id=current_setting('body_test.fw')::uuid),true);
select ok((select slot_identity::text<>current_setting('body_test.day') from workout_movements where id=current_setting('body_test.fm')::uuid),'favorite slot does not impersonate source identity');
select set_config('body_test.fe',select_program_exercise(current_setting('body_test.fm')::uuid,(select id from exercises where slug='barbell_bench_press'),null,md5('favorite_pick')::uuid)::text,true);
select is((select count(*)::int from workout_sets where workout_exercise_id=current_setting('body_test.fe')::uuid),2,'saved prescribed set count reused');
select ok((select bool_and(status='pending' and actual_reps is null and actual_weight_kg is null and effort_scale is null and effort_value is null and not performed_to_failure and not inputs_confirmed) from workout_sets where workout_exercise_id=current_setting('body_test.fe')::uuid),'favorite selected sets have no completed work/load/actual effort');
select lives_ok($$update favorite_workouts set name='Renamed' where id=current_setting('body_test.favorite')::uuid$$,'owned favorite rename');
select is((select name from workout_sessions where id=current_setting('body_test.fw')::uuid),'Saved press','rename does not rewrite running session name');
select lives_ok($$update favorite_workouts set archived=true where id=current_setting('body_test.favorite')::uuid$$,'owned favorite removal is archival');
select is((select jsonb_array_length(favorite_definition) from workout_sessions where id=current_setting('body_test.fw')::uuid),1,'removal does not remove active snapshot');
select end_workout(current_setting('body_test.fw')::uuid,'completed');
select is(program_schedule_cursor(current_setting('body_test.a')::uuid)::text,current_setting('body_test.before'),'even closed independent favorite never resolves assigned work');
select throws_ok($$select start_favorite_workout(current_setting('body_test.favorite')::uuid,md5('archived_start')::uuid)$$,'42501',null,'archived favorite cannot be launched');
select throws_ok($$update favorite_workouts set definition='[]' where id=current_setting('body_test.favorite')::uuid$$,'42501',null,'arbitrary favorite snapshot writes denied');
select throws_ok($$delete from favorite_workouts where id=current_setting('body_test.favorite')::uuid$$,'42501',null,'hard favorite deletion denied');
select set_config('body_test.adhoc',start_ad_hoc_workout()::text,true);
select set_config('body_test.ai',edit_workout(current_setting('body_test.adhoc')::uuid,'add',(select id from exercises where slug='barbell_bench_press'))::text,true);
select log_workout_set(p_item=>current_setting('body_test.ai')::uuid,p_id=>(select id from workout_sets where workout_exercise_id=current_setting('body_test.ai')::uuid order by position limit 1),p_operation=>'save',p_revision=>0,p_mutation=>md5('adhoc_favorite_set')::uuid,p_reps=>8,p_weight=>75,p_type=>'working',p_completed=>true,p_effort=>'{"scale":"rpe","value":9,"failure":true}'::jsonb);
select end_workout(current_setting('body_test.adhoc')::uuid,'completed');
select set_config('body_test.af',save_favorite_workout('completed_ad_hoc',current_setting('body_test.adhoc')::uuid,null,'My ad-hoc press',md5('favorite_adhoc')::uuid)::text,true);
select is((select source_type from favorite_workouts where id=current_setting('body_test.af')::uuid),'completed_ad_hoc','confirmed ad-hoc structure saved');
select ok((select not(definition->0 ?| array['actual_reps','actual_weight_kg','completed_at','status','duration','performed_to_failure']) from favorite_workouts where id=current_setting('body_test.af')::uuid),'source actual performance is not in template');
select ok((select not(definition->0 ? 'weight_kg') from favorite_workouts where id=current_setting('body_test.af')::uuid),'historical working weights are not template prescriptions');
select is((select (definition->0->>'target_sets')::int from favorite_workouts where id=current_setting('body_test.af')::uuid),3,'unprescribed ad-hoc structure uses explicit sensible defaults');
select set_config('body_test.aw',start_favorite_workout(current_setting('body_test.af')::uuid,md5('favorite_adhoc_start')::uuid)::text,true);
select is((select source_program_version_id from workout_sessions where id=current_setting('body_test.aw')::uuid),null::uuid,'ad-hoc favorite is independent');
select set_config('body_test.awm',(select id::text from workout_movements where workout_session_id=current_setting('body_test.aw')::uuid),true);
select set_config('body_test.awe',select_program_exercise(current_setting('body_test.awm')::uuid,(select id from exercises where slug='barbell_bench_press'),null,md5('adhoc_favorite_fresh_pick')::uuid)::text,true);
select ok((select bool_and(effort_scale is null and effort_value is null and not performed_to_failure) from workout_sets where workout_exercise_id=current_setting('body_test.awe')::uuid),'reported source RPE/failure is never copied as actual effort');
select ok((select bool_and(actual_weight_kg is null and actual_reps is null and status='pending') from workout_sets where workout_exercise_id=current_setting('body_test.awe')::uuid),'new favorite actual performance stays clean despite historical load suggestions');
select end_workout(current_setting('body_test.aw')::uuid,'abandoned');
select set_config('body_test.empty',start_ad_hoc_workout()::text,true);
select end_workout(current_setting('body_test.empty')::uuid,'completed');
select throws_ok($$select save_favorite_workout('completed_ad_hoc',current_setting('body_test.empty')::uuid,null,'Empty',md5('empty_save')::uuid)$$,'23514',null,'empty/unconfirmed selections cannot fabricate favorite structure');
select throws_ok($$select save_favorite_workout('completed_ad_hoc',current_setting('body_test.aw')::uuid,null,'Abandoned',md5('abandoned_save')::uuid)$$,'42501',null,'abandoned history not a favorite source');

select set_config('body_test.root',(select program_id::text from program_versions where id=current_setting('body_test.v')::uuid),true);
update program_slots set target_sets=4 where program_day_id in(select id from program_days where program_id=current_setting('body_test.root')::uuid);
select set_config('body_test.vnew',snapshot_program(current_setting('body_test.root')::uuid)::text,true);
select is((select (definition->0->>'target_sets')::int from favorite_workouts where id=current_setting('body_test.favorite')::uuid),2,'later recipe edits/version snapshots do not mutate favorite');
select throws_ok($$update program_versions set definition='{}' where id=current_setting('body_test.v')::uuid$$,'42501',null,'favorite does not grant source publication/edit rights');
reset role;
-- Trusted source retirement only, inside this rolled-back local fixture.
delete from workout_sessions where id=current_setting('body_test.adhoc')::uuid;
set local role authenticated;
select is((select source_session_id from favorite_workouts where id=current_setting('body_test.af')::uuid),null::uuid,'source deletion clears the optional pointer without deleting favorite');
select is((select jsonb_array_length(definition) from favorite_workouts where id=current_setting('body_test.af')::uuid),1,'source deletion preserves immutable saved structure');
select set_config('body_test.v8',pg_temp.rotation(8)::text,true);
select set_config('body_test.w8',start_program_workout(current_setting('body_test.v8')::uuid,1,md5('options_8')::uuid)::text,true);
select is(jsonb_array_length(workout_start_options()->'assignment'->'days'),4,'eight-position choices exclude rest');
select end_workout(current_setting('body_test.w8')::uuid,'abandoned');
select throws_ok($$select decide_program_schedule(current_setting('body_test.a')::uuid,current_setting('body_test.v')::uuid,current_setting('body_test.day')::uuid,1,4,5,'skip',md5('archived_decision')::uuid)$$,'23514',null,'archived assignment cannot accept new decisions');
select set_config('body_test.v10',pg_temp.rotation(10)::text,true);
select set_config('body_test.w10',start_program_workout(current_setting('body_test.v10')::uuid,1,md5('options_10')::uuid)::text,true);
select is(jsonb_array_length(workout_start_options()->'assignment'->'days'),5,'ten-position choices retain all training identities');
select end_workout(current_setting('body_test.w10')::uuid,'abandoned');
select set_config('body_test.v3',pg_temp.rotation(3)::text,true);
select set_config('body_test.w3',start_program_workout(current_setting('body_test.v3')::uuid,1,md5('options_3')::uuid)::text,true);
select is(jsonb_array_length(workout_start_options()->'assignment'->'days'),2,'three-position choices retain their real nonweekly shape');
select end_workout(current_setting('body_test.w3')::uuid,'abandoned');
-- A trusted local catalog retirement cannot destroy saved structure. Users
-- must explicitly choose another supported canonical exercise at execution.
reset role;
update exercises set archived_at=clock_timestamp() where slug='barbell_bench_press';
set local role authenticated;
select set_config('body_test.fallback',start_favorite_workout(current_setting('body_test.af')::uuid,md5('fallback_start')::uuid)::text,true);
select set_config('body_test.fallback_m',(select id::text from workout_movements where workout_session_id=current_setting('body_test.fallback')::uuid),true);
select lives_ok($$select select_program_exercise(current_setting('body_test.fallback_m')::uuid,(select id from exercises where slug='dumbbell_bench_press'),null,md5('fallback_pick')::uuid)$$,'unavailable saved default allows explicit supported substitution');
select ok((select definition->0->>'exercise_id'=(select id::text from exercises where slug='barbell_bench_press') from favorite_workouts where id=current_setting('body_test.af')::uuid),'current substitution does not rewrite saved default');
select end_workout(current_setting('body_test.fallback')::uuid,'abandoned');
reset role;
update exercises set archived_at=null where slug='barbell_bench_press';
-- Cap fixtures are privileged, synthetic and rolled back; normal saves never
-- accept these caller-authored snapshots.
insert into favorite_workouts(owner_id,name,source_type,source_key,definition,attribution,save_request)
 select md5('selection_a')::uuid,'Cap fixture '||i,'completed_ad_hoc','cap-'||i,(select definition from favorite_workouts where id=current_setting('body_test.af')::uuid),'{}',md5('cap-'||i)::uuid from generate_series(1,99)i;
set local role authenticated;
select throws_ok($$update favorite_workouts set archived=false where id=current_setting('body_test.favorite')::uuid$$,'23514',null,'direct restore cannot bypass 100-active-favorite cap');
select is((select count(*)::int from favorite_workouts where not archived),100,'cap does not remove existing favorites');
select set_config('request.jwt.claims',json_build_object('sub',md5('selection_b')::uuid,'role','authenticated')::text,true);
select is((select count(*)::int from favorite_workouts),0,'foreign favorites hidden by RLS');
select is((select count(*)::int from program_schedule_decisions),0,'foreign decisions hidden by RLS');
select throws_ok($$select start_favorite_workout(current_setting('body_test.af')::uuid,md5('foreign_start')::uuid)$$,'42501',null,'foreign favorite cannot be started');
select throws_ok($$select save_favorite_workout('completed_ad_hoc',current_setting('body_test.adhoc')::uuid,null,'Foreign',md5('foreign_save')::uuid)$$,'42501',null,'foreign completed source denied');
select throws_ok($$select save_favorite_workout('program_day',current_setting('body_test.v')::uuid,current_setting('body_test.day')::uuid,'Foreign',md5('foreign_program_save')::uuid)$$,'42501',null,'foreign private version denied');
select is((workout_start_options()->'favorites'),'[]'::jsonb,'start page read does not leak other favorites');
select ok(not has_table_privilege(r,'public.favorite_workouts','SELECT'),'favorite table denied to '||r) from unnest(array['anon','service_role'])r;
select ok(not has_function_privilege(r,'public.start_favorite_workout(uuid,uuid)','EXECUTE'),'favorite start denied to '||r) from unnest(array['anon','service_role'])r;
select ok(not has_function_privilege(r,'public.decide_program_schedule(uuid,uuid,uuid,integer,bigint,bigint,text,uuid,uuid,date)','EXECUTE'),'schedule writes denied to '||r) from unnest(array['anon','service_role'])r;
select * from finish();rollback;
